import Foundation
import simd

/// CPU-only harness. Fixtures are generated by the companion Python test; no
/// Rockstar model bytes are embedded in the public test source.
@main struct RenderWareDFFSmoke {
    static func matrix(_ m: simd_float4x4) -> [Double] {
        (0..<16).map { Double(m[$0 / 4][$0 % 4]) }
    }
    static func f2(_ a: SIMD2<Float>) -> [Double] { [Double(a.x), Double(a.y)] }
    static func f3(_ a: SIMD3<Float>) -> [Double] { [Double(a.x), Double(a.y), Double(a.z)] }
    static func f4(_ a: SIMD4<Float>) -> [Double] { [Double(a.x), Double(a.y), Double(a.z), Double(a.w)] }
    static func u4(_ a: SIMD4<UInt8>) -> [Int] { [Int(a.x), Int(a.y), Int(a.z), Int(a.w)] }
    static func describe(_ model: NativeRenderWareDFF, full: Bool) -> [String: Any] {
        var result: [String: Any] = ["version": model.version, "frames": model.frames.count,
            "geometries": model.geometries.count, "atomics": model.atomics.count,
            "vertices": model.geometries.map(\.vertexCount),
            "triangles": model.geometries.map { $0.triangles.count },
            "skins": model.geometries.map { $0.skin?.boneCount ?? 0 }]
        guard full else { return result }
        result["frameData"] = model.frames.map { frame -> [String: Any] in
            var row: [String: Any] = ["name": frame.name ?? "", "parent": frame.parent,
                "flags": frame.flags, "local": matrix(frame.localTransform), "world": matrix(frame.worldTransform)]
            if let h = frame.hierarchy {
                row["hierarchy"] = ["version": h.version, "id": h.id, "flags": h.flags,
                                    "keyFrameSize": h.keyFrameSize,
                                    "nodes": h.nodes.map { [Int($0.id), $0.index, Int($0.flags)] }] as [String: Any]
            }
            return row
        }
        result["atomicData"] = model.atomics.map { [$0.frame, $0.geometry, Int($0.flags), Int($0.unused)] }
        result["geometryData"] = model.geometries.map { geometry -> [String: Any] in
            var row: [String: Any] = ["flags": Int(geometry.flags),
                "uv": geometry.textureCoordinates.map { $0.map(f2) },
                "prelit": geometry.prelitColors.map(u4),
                "triangles": geometry.triangles.map { [Int($0.a), Int($0.b), Int($0.c), Int($0.material)] },
                "morphs": geometry.morphTargets.map { ["sphere": f4($0.boundingSphere),
                    "positions": $0.positions.map(f3), "normals": $0.normals.map(f3)] as [String: Any] },
                "materials": geometry.materials.map { material -> [String: Any] in
                    var m: [String: Any] = ["flags": material.flags, "color": u4(material.color)]
                    if let name = material.textureName { m["texture"] = name }
                    if let mask = material.maskName { m["mask"] = mask }
                    if let filter = material.textureFilterAndAddressing { m["filter"] = filter }
                    if let surface = material.surface { m["surface"] = f3(surface) }
                    return m
                }]
            if let skin = geometry.skin {
                row["skin"] = ["bones": skin.boneCount, "used": skin.usedBones.map(Int.init),
                    "maxWeights": skin.maximumWeights, "indices": skin.indices.map(u4),
                    "weights": skin.weights.map(f4), "inverse": skin.inverseBindMatrices.map(matrix)] as [String: Any]
            }
            return row
        }
        return result
    }
    static func main() throws {
        let manifest = try JSONSerialization.jsonObject(with: Data(contentsOf:
            URL(fileURLWithPath: CommandLine.arguments[1]))) as! [[String: Any]]
        let output = URL(fileURLWithPath: CommandLine.arguments[2])
        var results: [[String: Any]] = []
        for item in manifest {
            let path = item["path"] as! String
            do {
                var limits = NativeRenderWareDFF.Limits()
                switch item["limits"] as? String {
                case "vertices": limits.verticesPerGeometry = 2
                case "chunks": limits.chunks = 2
                case "file": limits.fileBytes = 12
                case "frames": limits.frames = 1
                case "materials": limits.materialsPerGeometry = 1
                case "totals": limits.totalVertices = 2
                case "uv": limits.textureCoordinateSets = 1
                case "bones": limits.bones = 1
                default: break
                }
                let model = try NativeRenderWareDFF.decode(Data(contentsOf: URL(fileURLWithPath: path)), limits: limits)
                results.append(["path": path, "accepted": true,
                                "model": describe(model, full: item["full"] as? Bool ?? false)])
            } catch {
                results.append(["path": path, "accepted": false, "error": String(describing: error)])
            }
        }
        try JSONSerialization.data(withJSONObject: results, options: [.sortedKeys]).write(to: output)
    }
}
